sys_ws_operation.script:
(function process(request, response) {

    var body = request.body ? request.body.data : null;
    if (!body) {
        response.setStatus(400);
        response.setBody(JSON.stringify({
            error: 'Missing request body',
            message: 'Provide a JSON body with an "action" field'
        }));
        return;
    }

    var action = body.action || '';
    var engine = new NACLAnalyticsEngine();
    var tracker = new NACLCostTracker();
    var result;

    switch (action) {
        case 'recalculate':
            var startDate = body.start_date || null;
            var endDate = body.end_date || null;
            var recalculatedCount = tracker.recalculateAll(startDate, endDate);
            result = {
                action: 'recalculate',
                status: 'completed',
                records_updated: recalculatedCount,
                message: 'All interaction costs recalculated with current config'
            };
            break;

        case 'forecast':
            var projDays = parseInt(body.projection_days) || 30;
            result = {
                action: 'forecast',
                status: 'completed',
                data: engine.forecastSpend(projDays)
            };
            break;

        case 'detect_waste':
            var wasteDays = parseInt(body.period_days) || 7;
            result = {
                action: 'detect_waste',
                status: 'completed',
                data: engine.detectWaste(wasteDays)
            };
            break;

        case 'optimize':
            result = {
                action: 'optimize',
                status: 'completed',
                data: engine.getOptimizationRecommendations()
            };
            break;

        default:
            response.setStatus(400);
            response.setBody(JSON.stringify({
                error: 'Unknown action: ' + action,
                supported_actions: ['recalculate', 'forecast', 'detect_waste', 'optimize']
            }));
            return;
    }

    response.setStatus(200);
    response.setBody(JSON.stringify(result));

})(request, response);

(function process(request, response) {

    var queryParams = request.queryParams || {};
    var report = queryParams.report || 'summary';
    var periodStr = queryParams.period || '30d';
    var feature = queryParams.feature || 'all';

    var periodDays = 30;
    if (periodStr === '7d') {
        periodDays = 7;
    } else if (periodStr === '90d') {
        periodDays = 90;
    } else if (periodStr === '30d') {
        periodDays = 30;
    }

    var engine = new NACLAnalyticsEngine();
    var result;

    switch (report) {
        case 'roi':
            result = {
                report: 'roi',
                period_days: periodDays,
                data: engine.computeROI(periodDays)
            };
            break;

        case 'waste':
            result = {
                report: 'waste',
                period_days: periodDays,
                data: engine.detectWaste(periodDays)
            };
            break;

        case 'forecast':
            result = {
                report: 'forecast',
                data: engine.forecastSpend(periodDays)
            };
            break;

        case 'summary':
            result = {
                report: 'summary',
                data: engine.getSummary()
            };
            break;

        case 'breakdown':
            var breakdown = engine.getFeatureBreakdown(periodDays);
            if (feature !== 'all') {
                var filtered = [];
                for (var i = 0; i < breakdown.features.length; i++) {
                    if (breakdown.features[i].feature_type === feature) {
                        filtered.push(breakdown.features[i]);
                    }
                }
                breakdown.features = filtered;
            }
            result = {
                report: 'breakdown',
                period_days: periodDays,
                feature_filter: feature,
                data: breakdown
            };
            break;

        case 'anomalies':
            result = {
                report: 'anomalies',
                data: {
                    anomalies: engine.checkAnomalies()
                }
            };
            break;

        default:
            response.setStatus(400);
            response.setBody(JSON.stringify({
                error: 'Unknown report type: ' + report,
                supported_reports: ['roi', 'waste', 'forecast', 'summary', 'breakdown', 'anomalies'],
                usage: 'GET /api/x_nacl/analytics?report=<type>&period=7d|30d|90d&feature=<type>'
            }));
            return;
    }

    response.setStatus(200);
    response.setBody(JSON.stringify(result));

})(request, response);
